// The screen fade (palette.c's gPaletteFade): the partner's colours follow it. A bitfield's value is
// (halfword at _OFF >> _SHIFT) & (_MASK >> _SHIFT); the masks come from agbcc's own layout of struct PaletteFadeControl
// (12 bytes), probed with every field set to all ones.
#define COOP_EM_gPaletteFade                                 0x02037FD4u
#define COOP_EM_PALFADE_SELECTED_OFF                         0   // offsetof(struct PaletteFadeControl, multipurpose1): selectedPalettes while a normal fade runs
#define COOP_EM_PALFADE_Y_OFF                                4   // y
#define COOP_EM_PALFADE_Y_SHIFT                              6
#define COOP_EM_PALFADE_Y_MASK                               0x07C0u
#define COOP_EM_PALFADE_BLEND_OFF                            6   // blendColor
#define COOP_EM_PALFADE_BLEND_SHIFT                          0
#define COOP_EM_PALFADE_BLEND_MASK                           0x7FFFu
#define COOP_EM_PALFADE_ACTIVE_OFF                           6   // active
#define COOP_EM_PALFADE_ACTIVE_SHIFT                         15
#define COOP_EM_PALFADE_ACTIVE_MASK                          0x8000u
#define COOP_EM_PALFADE_MODE_OFF                             8   // mode
#define COOP_EM_PALFADE_MODE_SHIFT                           8
#define COOP_EM_PALFADE_MODE_MASK                            0x0300u
